(function(){const status=document.getElementById('status');document.getElementById('check').addEventListener('click',function(){status.textContent='Checking signed releases…';if(window.VyomBridge&&typeof window.VyomBridge.checkForUpdates==='function'){window.VyomBridge.checkForUpdates()}else{status.textContent='Native update bridge unavailable'}});document.getElementById('selfchange').addEventListener('click',function(){if(window.VyomBridge&&typeof window.VyomBridge.openSelfChange==='function'){window.VyomBridge.openSelfChange()}else{status.textContent='Native self-change bridge unavailable'}});if(window.VyomBridge&&typeof window.VyomBridge.bundleVersion==='function'){document.getElementById('version').textContent='Bundle v'+window.VyomBridge.bundleVersion()}})();